<?php
session_start(); header('Content-Type: application/json; charset=utf-8');
if(($_SESSION['auth_user']['role']??'')!=='admin'){http_response_code(403);echo json_encode(['success'=>false,'message'=>'Không có quyền.']);exit;}
if(empty($_FILES['image'])||$_FILES['image']['error']!==UPLOAD_ERR_OK||$_FILES['image']['size']>5*1024*1024){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Chỉ nhận ảnh tối đa 5 MB.']);exit;}
$info=@getimagesize($_FILES['image']['tmp_name']);if(!$info||!in_array($info[2],[IMAGETYPE_JPEG,IMAGETYPE_PNG,IMAGETYPE_WEBP],true)||!function_exists('imagewebp')){http_response_code(422);echo json_encode(['success'=>false,'message'=>'Cần ảnh JPG/PNG/WebP và PHP GD có hỗ trợ WebP.']);exit;}
$source=match($info[2]){IMAGETYPE_JPEG=>imagecreatefromjpeg($_FILES['image']['tmp_name']),IMAGETYPE_PNG=>imagecreatefrompng($_FILES['image']['tmp_name']),IMAGETYPE_WEBP=>imagecreatefromwebp($_FILES['image']['tmp_name'])};$scale=min(1,1920/$info[0]);$w=max(1,(int)round($info[0]*$scale));$h=max(1,(int)round($info[1]*$scale));$out=imagecreatetruecolor($w,$h);imagealphablending($out,false);imagesavealpha($out,true);imagecopyresampled($out,$source,0,0,0,0,$w,$h,$info[0],$info[1]);$dir=__DIR__.'/images/uploads';if(!is_dir($dir))mkdir($dir,0755,true);$file='upload-'.date('Ymd-His').'-'.bin2hex(random_bytes(4)).'.webp';imagewebp($out,$dir.'/'.$file,80);imagedestroy($source);imagedestroy($out);echo json_encode(['success'=>true,'path'=>'images/uploads/'.$file]);
